function isolateRule(){const item=selectedRule();if(!item)return null;if(item.b.faces.length===1)return item.b;const copy=clone(item.b);copy.id=freshId(activeFace+'-',config.boundaries);copy.faces=[activeFace];item.b.faces=item.b.faces.filter(f=>f!==activeFace);config.boundaries.push(copy);activeBoundary=copy.id;return copy;}
