function thermalDefaults(type){return type==='fixed_temperature'?{type,temperature:config.physics.thermal.initial_temperature}:type==='heat_flux'?{type,heat_flux:0}:type==='convection'?{type,ambient_temperature:config.physics.thermal.initial_temperature,heat_transfer_coefficient:10}:{type};}
