function rotatePoint(p,axis,degrees){const norm=Math.hypot(...axis)||1,a=axis.map(v=>v/norm),r=degrees*Math.PI/180,c=Math.cos(r),s=Math.sin(r),dot=a.reduce((n,v,i)=>n+v*p[i],0),cross=[a[1]*p[2]-a[2]*p[1],a[2]*p[0]-a[0]*p[2],a[0]*p[1]-a[1]*p[0]];return p.map((v,i)=>v*c+cross[i]*s+a[i]*dot*(1-c));}
