function editorContent(){return JSON.stringify(jsonMode==='refinement'?refinement:config,null,2);}
function switchEditor(kind){jsonMode=kind;$('#ss-editor').value=editorContent();$('#ss-json-error').textContent='';$$('[data-json-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.jsonMode===kind));$('#ss-json-note').textContent=kind==='refinement'?'界面字段草案 · 不传给 V2.0.0 · 算法预研后确定正式格式':'V2.0.0 算例 · 均匀网格配置 · 不包含局部加密草稿';$('#ss-editor').setAttribute('aria-label',kind==='refinement'?'局部加密草稿 JSON':'高级 JSON 配置');$('#ss-editor').scrollTop=0;}
