function closeEditor(){ $('#ss-json-cover').hidden=true;$('.ss-scene').inert=false;$('.ss-inspector').inert=false;$('.ss-tree').inert=false;$('#ss-scene-title').textContent=mode==='results'?'结果视图':'几何视图';$('#ss-open-json').focus();draw();}
