function restore(s){const p=s?.privateContent;if(!p||![2,3,4].includes(p.revision)||JSON.stringify(p)===lastSnapshot)return;restoring=true;try{if(p.config){validate(p.config);config=clone(p.config);config.domain.origin??=[0,0,0];}if(p.refinement){validateRefinement(p.refinement);refinement=clone(p.refinement);activeRegion=refinement.regions.some(r=>r.id===p.activeRegion)?p.activeRegion:refinement.regions[0]?.id||null;previewRefinement=p.previewRefinement!==false;}if(p.revision===4){if(faceNames.includes(p.activeFace))activeFace=p.activeFace;activeBoundary=p.activeBoundary||null;if(['flow','thermal','scope'].includes(p.boundaryTab))boundaryTab=p.boundaryTab;if(['surface','geometry','motion','thermal'].includes(p.geoTab))geoTab=p.geoTab;geoIndex=Math.max(0,Math.min(Number(p.geoIndex)||0,config.geometry.length-1));}}catch{}if(['left','right'].includes(p.layout))design.layout=p.layout;root.dataset.layout=design.layout;$('#ss-ref-visible').checked=previewRefinement;syncMesh();updateMeta();if(['setup','run','results'].includes(p.mode))setMode(p.mode);if(p.revision===4&&['domain','grid','refinement','geometry','physics','fluid','boundary','solver','output','task'].includes(p.selected))choose(p.selected);else choose('boundary');draw();restoring=false;lastSnapshot=JSON.stringify(p);}
